// Normalises an incoming reply from either the Gmail Trigger or the IMAP Trigger.
// Also recognises delivery-failure notices (bounces) in plain code: hard failures only, delays are ignored.
const addr = (v) => {
  if (!v) return '';
  if (typeof v === 'string') { const m = v.match(/<([^>]+)>/); return (m ? m[1] : v).trim(); }
  return (v.value && v.value[0] && v.value[0].address) || '';
};
return $input.all().map((it, i) => {
  const j = it.json;
  const isGmail = !!j.threadId;
  const subject = String(j.subject || '');
  const text = String(j.text || j.textPlain || '');
  const from = addr(j.from).toLowerCase();
  const fromText = from + ' ' + (typeof j.from === 'string' ? j.from : String((j.from && j.from.text) || ''));
  const daemon = /mailer-daemon|postmaster|mail delivery (sub)?system/i.test(fromText);
  const failSubj = /undeliver|delivery status notification|delivery (has )?failed|mail delivery failed|returned to sender|failure notice|teslim edilemedi|iletilemedi|ulaştırılamadı/i.test(subject);
  const delay = /\bdelay|warning|gecik|still (being )?(undelivered|retried)|will be retried|temporar/i.test(subject);
  const hardRe = /\b5\.\d{1,3}\.\d{1,3}\b|\b55\d\b|user unknown|no such user|does not exist|unknown recipient|recipient address rejected|mailbox unavailable|mailbox not found|address not found|domain name not found|domain not found|permanent/i;
  const hard = hardRe.test(text + ' ' + subject);
  const isBounce = (daemon || failSubj) && !delay && (hard || failSubj);
  const reasonLine = text.split(/\r?\n/).map(l => l.trim()).find(l => hardRe.test(l)) || subject;
  return {
    json: {
      source: isGmail ? 'gmail' : 'imap',
      message_id: isGmail ? j.id : String(j.messageId || ''),
      thread_id: isGmail ? j.threadId : '',
      in_reply_to: isGmail ? '' : String(j.inReplyTo || ''),
      references: isGmail ? '' : (Array.isArray(j.references) ? j.references.join(' ') : String(j.references || '')),
      subject,
      text,
      from,
      to: addr(j.to),
      is_bounce: isBounce,
      bounce_reason: isBounce ? String(reasonLine).slice(0, 250) : '',
    },
    pairedItem: { item: i },
  };
});

// Matches each reply to its lead. No match = the reply is ignored.
// Gmail: by Gmail Thread ID. IMAP/SMTP: by In-Reply-To/References against the stored 'smtp:<Message-ID>',
// then by sender = lead email, then by subject (without Re:/Ynt:) among leads still in Sent / Follow-up stages.
// Bounces: by the same ids, then by our Message-ID or the lead's address quoted inside the failure notice.
// _siblings = the firm's other contact rows (second contact rows carry 'Parent Lead ID') that are still active.
const replies = $('Reply').all().map(i => i.json);
const leads = $('Get Leads (reply)').all().map(i => i.json).filter(r => r && r['Lead ID']);
const norm = (s) => String(s || '').replace(/[<>]/g, '').trim().toLowerCase();
const baseSubj = (s) => String(s || '').replace(/^\s*((re|ynt|aw|fw|fwd|ynt\.)\s*:\s*)+/i, '').trim().toLowerCase();
const open = ['Sent', 'Follow-up 1', 'Follow-up 2', 'Follow-up 3'];
const active = ['Researched', 'Drafted', 'Waiting - 2nd contact', 'Sent', 'Follow-up 1', 'Follow-up 2', 'Follow-up 3'];
const root = (l) => String(l['Parent Lead ID'] || '').trim() || String(l['Lead ID']).trim();
const out = [];
for (const r of replies) {
  let lead;
  if (r.source === 'gmail') {
    lead = leads.find(l => String(l['Gmail Thread ID'] || '') === r.thread_id);
  } else {
    const ids = (r.in_reply_to + ' ' + r.references).split(/\s+/).map(norm).filter(Boolean);
    lead = leads.find(l => { const t = String(l['Gmail Thread ID'] || ''); return t.startsWith('smtp:') && ids.includes(norm(t.slice(5))); });
    if (r.is_bounce) {
      const low = String(r.text || '').toLowerCase();
      const sent = leads.filter(l => String(l['Sent At'] || '').trim());
      if (!lead) lead = sent.find(l => { const t = String(l['Gmail Thread ID'] || ''); return t.startsWith('smtp:') && norm(t.slice(5)) && low.includes(norm(t.slice(5))); });
      if (!lead) lead = sent.find(l => open.includes(l.Stage) && norm(l.Email) && low.includes(norm(l.Email)));
    } else {
      if (!lead) lead = leads.find(l => open.includes(l.Stage) && r.from && norm(l.Email) === r.from);
      if (!lead) { const s = baseSubj(r.subject); if (s) lead = leads.find(l => open.includes(l.Stage) && baseSubj(l.Subject) === s); }
    }
  }
  if (lead) {
    const siblings = leads.filter(l => l['Lead ID'] !== lead['Lead ID'] && root(l) === root(lead) && active.includes(l.Stage)).map(l => l['Lead ID']);
    out.push({ json: { ...lead, _reply: r, _siblings: siblings } });
  }
}
return out;

